using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MinimumVariableSoulHeatCastAction", menuName = "Data/Battle/Battle Actions/Sothis/MinimumVariableSoulHeatCast Action")]
public class MinimumVariableSoulHeatCastAction : MultipleSoulHeatTierAction
{
	public override bool CheckConditionToBeCasted(int actionValue, bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (GetSoulHeatAmountToUse(activateFeedback: false) >= actionValue)
		{
			return battleAction.CheckConditionToBeCasted(playerHand, DiceOwnerEnum.PLAYER);
		}
		return true;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		CastMultipleSoulHeatTierFirstActionSoulHeatVariableAction(delegate
		{
			battleAction.Cast(source);
		}, null, null, amount, source);
	}
}
